('a61d92b5-f36e-5a2b-b3fd-422421382f45'::uuid,'est','"Statistics, Probability & Data Analysis"'::jsonb,'easy','mcq','"A distance in meters, M, can be approximated by multiplying a distance in yards, Y, by 1.0936. Which of the following expressions expresses this approximation method? (Note: The symbol ≈ means \"is approximately equal to.\")"'::jsonb,'[{"key":"A","text":"M ≈ Y/1.0936"},{"key":"B","text":"M ≈ 1.0936/Y"},{"key":"C","text":"M ≈ Y(1.0936)"},{"key":"D","text":"M ≈ Y + 1.0936"},{"key":"E","text":"M ≈ Y(1.0936Y)"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-03","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"C"'::jsonb,'"Source-keyed answer from pt2.md (P2-03)."'::jsonb),
