('8fb512c0-537a-5d4b-8151-fb9c03c73edb'::uuid,'est','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','mcq','"Which of the following operations will produce the smallest result when substituted for the blank in the expression: (2/3) ____ − 3?"'::jsonb,'[{"key":"A","text":"plus"},{"key":"B","text":"minus"},{"key":"C","text":"multiplied by"},{"key":"D","text":"divided by"},{"key":"E","text":"averaged with"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-43","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"A"'::jsonb,'"Source-keyed answer from pt2.md (P2-43)."'::jsonb),
