('b2fb3fc5-63bd-5058-b546-afd48f1a6ddd'::uuid,'est','"Sequences, Complex Numbers & Advanced Algebra"'::jsonb,'medium','mcq','"What is the solution set of |3a − 2| ≤ 7?"'::jsonb,'[{"key":"A","text":"{a: a ≤ 3}"},{"key":"B","text":"{a: −5/3 ≤ a ≤ 3}"},{"key":"C","text":"{a: −5/3 ≥ a ≥ 3}"},{"key":"D","text":"{a: −5/3 ≤ a ≥ 3}"},{"key":"E","text":"{a: −5/3 ≥ a ≤ 3}"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-45","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Sequences, Complex Numbers & Advanced Algebra"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from pt2.md (P2-45)."'::jsonb),
('5912228e-2355-547d-ad15-765fc679e6b3'::uuid,'est','"Triangles, Trigonometry & Similarity"'::jsonb,'medium','mcq','"When measured from a point on the ground that is a certain distance from the base of a cell phone tower, the angle of elevation to the top of the tower is 41°, as shown below. The height of the cell phone tower is 200 feet. What is the distance, in feet, to the cell phone tower?\n[Figure: Right triangle; vertical leg 200 ft (tower); angle of elevation 41° at the ground point; horizontal leg labeled Distance (?).]"'::jsonb,'[{"key":"F","text":"200 tan 41°"},{"key":"G","text":"200 sin 41°"},{"key":"H","text":"200 cos 41°"},{"key":"J","text":"200 sec 41°"},{"key":"K","text":"200 cot 41°"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-46","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Triangles, Trigonometry & Similarity","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/P2-46.png","image_alt":"Original graph, diagram, or table for P2-46","visual_verified":true}'::jsonb,'"K"'::jsonb,'"Source-keyed answer from pt2.md (P2-46)."'::jsonb),
