('2c625595-9027-5849-b37d-b4ce60e4b69c'::uuid,'est','"Functions, Transformations & Graphs"'::jsonb,'medium','mcq','"If a system of 2 linear equations in 2 variables has NO solution, and 1 of the equations is graphed in the (x, y) coordinate plane below, which of the following could be the equation of the other line?\n[Figure: Line through (3, 0) and (0, −4).]"'::jsonb,'[{"key":"F","text":"y = −2"},{"key":"G","text":"y = −(1/4)x + 2"},{"key":"H","text":"y = −2x − 4"},{"key":"J","text":"y = (4/3)x + 2"},{"key":"K","text":"y = 4x − 4"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-52","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Functions, Transformations & Graphs","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/P2-52.png","image_alt":"Original graph, diagram, or table for P2-52","visual_verified":true}'::jsonb,'"J"'::jsonb,'"Source-keyed answer from pt2.md (P2-52)."'::jsonb),
('5b092206-92ed-59e4-864d-7b7f8e2a9855'::uuid,'est','"Statistics, Probability & Data Analysis"'::jsonb,'hard','mcq','"In a game, 80 marbles numbered 00 through 79 are placed in a box. A player draws 1 marble at random from the box. Without replacing the first marble, the player draws a second marble at random. If both marbles drawn have the same ones digit (that is, both marbles have a number ending in 0, 1, 2, 3, etc.), the player is a winner. If the first marble drawn is numbered 35, what is the probability that the player will be a winner on the next draw?"'::jsonb,'[{"key":"A","text":"1/79"},{"key":"B","text":"7/80"},{"key":"C","text":"7/79"},{"key":"D","text":"1/10"},{"key":"E","text":"8/79"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-53","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"C"'::jsonb,'"Source-keyed answer from pt2.md (P2-53)."'::jsonb),
('f1148a9f-a99f-5c3f-b46d-724a454a9384'::uuid,'est','"Coordinate Geometry, Circles & Conics"'::jsonb,'medium','mcq','"In the standard (x, y) coordinate plane, what is the equation of the line that passes through the origin and the point (3, 4)?"'::jsonb,'[{"key":"F","text":"y = (1/4)x + 3/4"},{"key":"G","text":"y = (1/4)x − 1/3"},{"key":"H","text":"y = (4/3)x"},{"key":"J","text":"y = (1/2)x + 3/4"},{"key":"K","text":"y = (9/4)x"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-54","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Coordinate Geometry, Circles & Conics"}'::jsonb,'"H"'::jsonb,'"Source-keyed answer from pt2.md (P2-54)."'::jsonb),
('94557afa-7945-599a-9100-5a5e90e22ef5'::uuid,'est','"Triangles, Trigonometry & Similarity"'::jsonb,'medium','mcq','"The measure of the vertex angle of an isosceles triangle is (a + 30)°. The base angles each measure (2a − 15)°. What is the measure in degrees of one of the base angles?"'::jsonb,'[{"key":"A","text":"36°"},{"key":"B","text":"45°"},{"key":"C","text":"57°"},{"key":"D","text":"66°"},{"key":"E","text":"90°"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-55","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Triangles, Trigonometry & Similarity"}'::jsonb,'"C"'::jsonb,'"Source-keyed answer from pt2.md (P2-55)."'::jsonb),
('6ae22ec9-afe5-507a-890f-8967b1cfbebd'::uuid,'est','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','mcq','"What is the smallest possible value for the product of 2 integers that differ by 7?"'::jsonb,'[{"key":"F","text":"8"},{"key":"G","text":"0"},{"key":"H","text":"−6"},{"key":"J","text":"−10"},{"key":"K","text":"−12"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-56","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"K"'::jsonb,'"Source-keyed answer from pt2.md (P2-56)."'::jsonb),
