('0568ea35-6d5a-5dfe-a728-2a4ecdfc1c0e'::uuid,'est','"Triangles, Trigonometry & Similarity"'::jsonb,'medium','mcq','"Given the vertices of parallelogram QRST in the standard (x, y) coordinate plane below, what is the area of triangle QRS, in square units?\n[Figure: Parallelogram with Q (−4, 3), R (2, 3), S (3, −5), T (−3, −5); dashed diagonal from Q to S.]"'::jsonb,'[{"key":"F","text":"24"},{"key":"G","text":"28"},{"key":"H","text":"48"},{"key":"J","text":"60"},{"key":"K","text":"80"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-58","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Triangles, Trigonometry & Similarity","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/P2-58.png","image_alt":"Original graph, diagram, or table for P2-58","visual_verified":true}'::jsonb,'"F"'::jsonb,'"Source-keyed answer from pt2.md (P2-58)."'::jsonb)
), inserted as (
 insert into public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
 select i.id,i.track_id,i.topic #>> '{}',i.difficulty,i.type,i.stem #>> '{}',i.choices,i.assets
 from imported i
 where not exists (select 1 from public.questions e where e.track_id='est' and lower(regexp_replace(e.stem,'[^a-z0-9]+','','g'))=lower(regexp_replace(i.stem #>> '{}','[^a-z0-9]+','','g')))
 on conflict (id) do update set topic=excluded.topic,difficulty=excluded.difficulty,type=excluded.type,stem=excluded.stem,choices=excluded.choices,assets=excluded.assets
 returning id
)
insert into public.question_keys(question_id,correct,explanation)
select i.id,i.correct,i.explanation #>> '{}' from imported i join public.questions q on q.id=i.id
on conflict (question_id) do update set correct=excluded.correct, explanation=excluded.explanation;
commit;
